const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
let ai = {};
try { ai = JSON.parse(raw); } catch {}
const faqSchema = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": (ai.faqs || []).map((f) => ({ "@type": "Question", "name": f.q, "acceptedAnswer": { "@type": "Answer", "text": f.a } }))
};
return [{ json: { ...ai, faqJsonLd: JSON.stringify(faqSchema) } }];
